/**
 * @bela/types — the shared domain contract for the BELA + DeskOne prototype.
 *
 * WHAT LIVES HERE: the string unions for every status/profile/kind stored on
 * the Prisma entities, plus PT-BR label maps. These are the vocabulary both
 * frontends (`apps/deskone`, future `apps/console-bela`) and the backend agree
 * on. The schema stores each as `String` (never a native DB enum) so the
 * SQLite↔Postgres swap stays trivial (Fase 1 constraint) — this file is what
 * makes those strings type-safe at the edges.
 *
 * WHAT DOES NOT LIVE HERE: the row/entity shapes. Those are generated by Prisma
 * and re-exported from `@bela/db` — deriving them twice would drift. Import
 * entity types from `@bela/db`, vocabulary from `@bela/types`.
 *
 * `rules.ts` also lives here: PROVISIONAL derivation rules (asset BIA
 * criticality + health score) — a demo stand-in for gaps the docs don't define
 * yet (CLAUDE.md §9). See `docs/regras-derivadas-provisorias.md`.
 */

export * from './common';
export * from './itsm';
export * from './bela';
export * from './predict';
export * from './console';
export * from './rules';
export * from './dto';
